(function(){
  'use strict';

  const onReady = (fn) => {
    if (document.readyState === 'loading') {
      document.addEventListener('DOMContentLoaded', fn);
    } else {
      fn();
    }
  };

  onReady(() => {
    const doc = document;

    // Cache key node lists (updated on resize)
    let sections = Array.from(doc.querySelectorAll('section[id]'));
    let navLinks = Array.from(doc.querySelectorAll('.nav-menu a'));
    let current = '';

    // Delegate clicks for internal anchors, buttons and external-link visual feedback
    doc.addEventListener('click', (e) => {
      const a = e.target.closest('a');
      if (!a) return;

      const href = a.getAttribute('href') || '';

      // Smooth in-page navigation (single delegated listener)
      if (href.startsWith('#')) {
        const target = doc.querySelector(href);
        if (target) {
          e.preventDefault();
          target.scrollIntoView({ behavior: 'smooth', block: 'start' });
        }
      }

      // Button click logging (handles .btn & descendants)
      if (a.classList && a.classList.contains('btn')) {
        const bookTitle = a.closest('.book-card')?.querySelector('.book-title')?.textContent;
        const linkType = a.classList.contains('btn-primary') ? 'PDF Download' : 'External Link';
        console.log(`User clicked: ${linkType} for ${bookTitle}`);
      }

      // Simple visual feedback for external links
      if (a.target === '_blank') {
        a.style.opacity = '0.6';
        setTimeout(() => { a.style.opacity = '1'; }, 300);
      }
    }, false);

    // IntersectionObserver for reveal animations (already efficient)
    const observerOptions = { threshold: 0.1, rootMargin: '0px 0px -100px 0px' };
    const observer = new IntersectionObserver((entries) => {
      requestAnimationFrame(() => {
        entries.forEach(entry => {
          if (entry.isIntersecting) {
            entry.target.classList.add('active');
            observer.unobserve(entry.target);
          }
        });
      });
    }, observerOptions);

    const revealElements = doc.querySelectorAll('.book-card,.section-title,.about-content,.hero-content');
    revealElements.forEach(el => {
      el.classList.add('reveal');
      observer.observe(el);
    });

    // Scroll indicator
    const scrollInd = doc.querySelector('.scroll-indicator');
    if (scrollInd) {
      scrollInd.addEventListener('click', () => {
        doc.getElementById('library')?.scrollIntoView({ behavior: 'smooth' });
      });
    }

    // Audio init (only if elements exist)
    const audioBtn = doc.getElementById('audio-toggle');
    const audio = doc.getElementById('temple-audio');
    if (audioBtn && audio) {
      let isPlaying = false;
      audio.volume = 0.4;
      audioBtn.addEventListener('click', () => {
        if (isPlaying) {
          audio.pause();
          audioBtn.classList.remove('playing');
          audioBtn.innerHTML = '<i class="fas fa-music"></i>';
        } else {
          audio.play().catch(() => {});
          audioBtn.classList.add('playing');
          audioBtn.innerHTML = '<i class="fas fa-volume-up"></i>';
        }
        isPlaying = !isPlaying;
      });
    }

    // Parallax: use requestAnimationFrame and passive scroll listener
    const heroBg = doc.querySelector('.hero-bg');
    if (heroBg) {
      let ticking = false;
      const heroSection = doc.querySelector('.hero');
      const updateParallax = () => {
        const scrolled = window.scrollY;
        if (!heroSection) { ticking = false; return; }
        const heroBottom = heroSection.offsetTop + heroSection.offsetHeight;
        if (scrolled <= heroBottom) {
          heroBg.style.transform = `translateY(${scrolled * 0.5}px)`;
        }
        ticking = false;
      };
      window.addEventListener('scroll', () => {
        if (!ticking) {
          requestAnimationFrame(updateParallax);
          ticking = true;
        }
      }, { passive: true });
      updateParallax();
    }

    // Active nav on scroll: cache selectors and RAF-throttle the handler
    let tickingNav = false;
    const onScrollNav = () => {
      if (!sections.length || !navLinks.length) { tickingNav = false; return; }
      const scrollPos = window.scrollY;
      let newCurrent = '';
      for (let i = 0; i < sections.length; i++) {
        const s = sections[i];
        if (scrollPos >= s.offsetTop - 200) newCurrent = s.id;
      }
      if (newCurrent !== current) {
        current = newCurrent;
        navLinks.forEach(link => link.classList.toggle('active', link.getAttribute('href').slice(1) === current));
      }
      tickingNav = false;
    };
    window.addEventListener('scroll', () => {
      if (!tickingNav) {
        requestAnimationFrame(onScrollNav);
        tickingNav = true;
      }
    }, { passive: true });

    // Update cached node lists on resize (passive)
    window.addEventListener('resize', () => {
      sections = Array.from(doc.querySelectorAll('section[id]'));
      navLinks = Array.from(doc.querySelectorAll('.nav-menu a'));
    }, { passive: true });

    // Keep API compatibility for any external calls in other scripts
    window.createMobileMenu = window.createMobileMenu || function(){};
    window.initParallax = window.initParallax || function(){};
    window.initAudio = window.initAudio || function(){};
  });
})();
